<?php require __DIR__.'/includes/bootstrap.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=db()->prepare('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.is_active=1');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('المنتج غير موجود');}?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($p['name'])?> | الفخامة</title><link rel="stylesheet" href="assets/css/store.css"></head><body><?php include __DIR__.'/includes/nav.php';?><main class="inner"><a href="index.php">الرئيسية</a> / <?=h($p['category_name'])?><div class="detail"><img src="<?=h($p['image_url'])?>" alt="<?=h($p['name'])?>"><div><h1><?=h($p['name'])?></h1><p><?=nl2br(h($p['description']))?></p><strong class="price"><?=money($p['price'])?></strong><p><?=((int)$p['stock']>0?'متوفر في المخزون':'غير متوفر حالياً')?></p><?php if((int)$p['stock']>0):?><form method="post" action="cart-action.php"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$p['id']?>"><label>الكمية <input type="number" name="quantity" value="1" min="1" max="<?=$p['stock']?>"></label><button class="gold">أضف إلى السلة</button></form><?php endif?></div></div></main><?php include __DIR__.'/includes/footer.php';?></body></html>